package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.*;
import org.junit.jupiter.api.Test;
/** Actual original preparation/permit around an explicit body delegate probe; full factory/worker composition is separate. */
class ReportProgramResultHandlerTest {
 boolean mysql(){return false;}
 ReportDispatchPermitTest h;ResultApplicationService.Input input;ReportProgramResultHandler handler;int calls;
 void setup()throws Exception{h=new ReportDispatchPermitTest(){@Override boolean mysql(){return ReportProgramResultHandlerTest.this.mysql();}};h.setup();calls=0;var original=h.original;var context=ReportPreparationInputProfile.complete(CanonicalJson.parse(original.input().snapshotJson())).command().applicationContext();input=context.input(original.input().ownerId(),JdbcFrozenInputs.stableId("attempt",original.input().ownerId()+":1"),original.input().inputHash(),0);var base=h.h.f.data.nativeData().fixture().f();ResultApplicationService.Handler delegate=(value,result,current,manual)->{calls++;return new ResultApplicationService.Applied(context.contentId(),1L);};handler=new ReportProgramResultHandler(delegate,new JdbcFrozenInputs(base.source),base.tx,h.permits);}
 ResultApplicationService.Applied apply(ResultApplicationService.Handler prepared,boolean manual){var base=h.h.f.data.nativeData().fixture().f();return base.writes.execute(base.action("fictional-program-report-apply"),k->null,a->prepared.apply(input,null,null,manual));}
 @Test void CompleteNativeProgramProofWrapsAutomaticAndManualDelegateOnlyInsideActualWriter()throws Exception{setup();var automatic=handler.prepare(input,null);assertNotNull(apply(automatic,false));assertEquals(1,calls);var manual=handler.prepareManual(input);assertNotNull(apply(manual,true));assertEquals(2,calls);assertEquals(2,h.h.f.data.nativeData().fixture().f().sends);}
 @Test void ChangedOriginalProgramAfterPreparationBlocksDelegateBeforeAnyBodyWrite()throws Exception{setup();var prepared=handler.prepare(input,null);var base=h.h.f.data.nativeData().fixture().f();base.jdbc.update("UPDATE jobs SET operator_id='fictional-invalid-program' WHERE target_type='generation_prepare' AND operator_id=?",JdbcReportPreparedInputs.ACTOR);assertThrows(RuntimeException.class,()->apply(prepared,false));assertEquals(0,calls);assertEquals(0L,base.jdbc.queryForObject("SELECT COUNT(*) FROM contents WHERE kind='report'",Long.class));}
 @Test void CallerCannotSkipPreparationOrChangeManualModeAndMissingProviderStaysClosed()throws Exception{setup();assertThrows(RuntimeException.class,()->handler.apply(input,null,null,false));var prepared=handler.prepare(input,null);assertThrows(RuntimeException.class,()->apply(prepared,true));assertThrows(RuntimeException.class,()->prepared.apply(input,null,null,false));var base=h.h.f.data.nativeData().fixture().f();var absent=new ReportProgramResultHandler((v,r,c,m)->null,new JdbcFrozenInputs(base.source),base.tx,null);assertThrows(RuntimeException.class,()->absent.prepare(input,null));assertThrows(RuntimeException.class,()->h.h.f.rr(()->handler.prepare(input,null)));assertEquals(0,calls);}
 @Test void DelegateFailureRollsBackNativeWriteAndKeepsOriginalPreparedInput()throws Exception{setup();var base=h.h.f.data.nativeData().fixture().f();long before=new JdbcJobRecords(base.source).byId(input.rootId()).revision();var fault=new ReportProgramResultHandler((value,result,current,manual)->{base.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",input.rootId());throw new IllegalStateException("fictional body failure");},new JdbcFrozenInputs(base.source),base.tx,h.permits);var prepared=fault.prepare(input,null);assertThrows(RuntimeException.class,()->apply(prepared,false));assertEquals(before,new JdbcJobRecords(base.source).byId(input.rootId()).revision());assertEquals(h.original,h.h.originals.find(h.original.scope()));var delegate=mock(ResultApplicationService.Handler.class);var inputs=mock(JdbcFrozenInputs.class);var tx=mock(org.springframework.transaction.PlatformTransactionManager.class);var permits=mock(ReportDispatchPermitService.class);new ReportProgramResultHandler(delegate,inputs,tx,permits);verifyNoInteractions(delegate,inputs,tx,permits);}
}
